'use strict';
const en=document.documentElement.lang==='en';
const tr=(fr,eng)=>en?eng:fr;
const menu=document.querySelector('.menu-toggle');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));document.querySelector('#mobile-menu').hidden=!open;});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&menu?.getAttribute('aria-expanded')==='true'){menu.click();menu.focus();}});
const reduce=matchMedia('(prefers-reduced-motion: reduce)');
const limited=navigator.connection?.saveData||['slow-2g','2g'].includes(navigator.connection?.effectiveType);
const vids=[...document.querySelectorAll('[data-video]')];
vids.forEach(v=>{const parent=v.closest('.hero,.wide-film,.image-wrap');const b=parent?.querySelector('[data-video-toggle]');const update=()=>{if(!b)return;b.textContent=v.paused?tr('Lire la vidéo','Play video'):tr('Mettre en pause','Pause video');b.setAttribute('aria-pressed',String(!v.paused));};v.addEventListener('play',update);v.addEventListener('pause',update);v.addEventListener('error',()=>{v.removeAttribute('src');v.load();if(b){b.textContent=tr('Vidéo indisponible','Video unavailable');b.disabled=true;}});b?.addEventListener('click',()=>{if(!v.src)v.src=v.dataset.src;if(v.paused){v.dataset.userPaused='false';v.play().catch(update);}else{v.dataset.userPaused='true';v.pause();}});});
const videoObserver=new IntersectionObserver(entries=>{for(const {target:v,isIntersecting} of entries){if(!isIntersecting){v.pause();continue;}if(!reduce.matches&&!limited&&v.dataset.userPaused!=='true'){if(!v.src)v.src=v.dataset.src;v.play().catch(()=>{});}}},{threshold:.15});vids.forEach(v=>videoObserver.observe(v));reduce.addEventListener('change',()=>{if(reduce.matches)vids.forEach(v=>v.pause());});document.addEventListener('visibilitychange',()=>{if(document.hidden)vids.forEach(v=>v.pause());});
if(!reduce.matches&&'IntersectionObserver'in window){document.body.classList.add('js-motion');const reveal=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveal.unobserve(e.target);}}),{threshold:.06});document.querySelectorAll('.reveal').forEach(e=>reveal.observe(e));}
if(matchMedia('(pointer:fine)').matches&&!reduce.matches){document.querySelectorAll('.service-card .image-wrap').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.transform=`perspective(1100px) rotateY(${(e.clientX-r.left-r.width/2)/r.width*1.3}deg)`;});el.addEventListener('pointerleave',()=>el.style.transform='');});}
const cookie=document.querySelector('#cookie-dialog');document.querySelectorAll('[data-cookie-open]').forEach(b=>b.addEventListener('click',()=>cookie.showModal()));document.querySelector('[data-cookie-close]')?.addEventListener('click',()=>cookie.close());document.querySelectorAll('[data-cookie-choice]').forEach(b=>b.addEventListener('click',()=>{try{localStorage.setItem('codem-privacy',b.dataset.cookieChoice);}catch{}cookie.close();}));
function validate(scope){let valid=true,first;scope.querySelectorAll('input,select,textarea').forEach(el=>{if(el.disabled||el.closest('[hidden]')||['checkbox','radio','hidden'].includes(el.type))return;const err=el.closest('.field')?.querySelector('.field-error');const ok=el.checkValidity();el.setAttribute('aria-invalid',String(!ok));if(err)err.textContent=ok?'':el.validity.valueMissing?tr('Veuillez compléter ce champ.','Please complete this field.'):tr('Veuillez vérifier cette information.','Please check this information.');if(!ok){valid=false;first??=el;}});first?.focus();return valid;}
function preference(form){const select=form.querySelector('[name="preference"]');if(!select)return;const apply=()=>{for(const field of ['email','telephone']){const input=form.querySelector(`[name="${field}"]`);if(!input)continue;input.required=select.value===field;const marker=input.closest('.field').querySelector('[data-required]');if(marker)marker.textContent=input.required?' *':'';}};select.addEventListener('change',apply);apply();}
document.querySelectorAll('form').forEach(form=>{preference(form);form.addEventListener('input',e=>{if(e.target.matches('input,textarea,select')){e.target.removeAttribute('aria-invalid');const err=e.target.closest('.field')?.querySelector('.field-error');if(err)err.textContent='';}});});
const quote=document.querySelector('#quote-form');let step=0;
if(quote){const sections=[...quote.querySelectorAll('.step')];const next=quote.querySelector('[data-next]'),prev=quote.querySelector('[data-prev]'),send=quote.querySelector('[data-submit]');const show=()=>{sections.forEach((s,i)=>s.hidden=i!==step);document.querySelectorAll('.steps-nav li').forEach((li,i)=>{li.classList.toggle('active',i===step);if(i===step)li.setAttribute('aria-current','step');else li.removeAttribute('aria-current');});document.querySelector('.progress-bar').style.width=`${(step+1)*25}%`;prev.hidden=step===0;next.hidden=step===3;send.hidden=step!==3;quote.querySelector('[data-step-counter]').textContent=tr(`Étape ${step+1} sur 4`,`Step ${step+1} of 4`);if(step===3)review();};function review(){const target=quote.querySelector('.review-values');target.replaceChildren();const fd=new FormData(quote);for(const [key,value] of fd.entries()){if(!value||['website','consent','email','telephone','nom','message'].includes(key))continue;const el=quote.querySelector(`[name="${key}"]`);const name=el?.closest('.field')?.querySelector('label')?.textContent||el?.closest('fieldset')?.querySelector('legend')?.textContent||key;const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=el?.tagName==='SELECT'?el.selectedOptions[0].textContent:value;target.append(dt,dd);}}next.addEventListener('click',()=>{if(validate(sections[step])){step++;show();sections[step].querySelector('h2').focus();}});prev.addEventListener('click',()=>{step=Math.max(0,step-1);show();});quote.querySelectorAll('[data-edit-step]').forEach(b=>b.addEventListener('click',()=>{step=Number(b.dataset.editStep);show();}));quote.querySelectorAll('[data-reveal]').forEach(c=>c.addEventListener('change',()=>{const box=quote.querySelector('#'+c.dataset.reveal);box.hidden=!c.checked;box.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=!c.checked);}));quote.addEventListener('submit',e=>{e.preventDefault();if(!validate(sections[step]))return;quote.querySelector('.form-status').textContent=tr('L’envoi en ligne n’est pas encore disponible. Vos réponses sont conservées sur cette page. Appelez CODEM au 01 71 36 18 38 pour poursuivre.','Online submission is not available yet. Your answers remain on this page. Call CODEM on +33 1 71 36 18 38 to continue.');});show();}
document.querySelector('#contact-form')?.addEventListener('submit',e=>{e.preventDefault();if(!validate(e.target))return;e.target.querySelector('.form-status').textContent=tr('L’envoi en ligne n’est pas encore disponible. Votre saisie est conservée. Appelez-nous au 01 71 36 18 38.','Online submission is not available yet. Your entries have been kept. Please call +33 1 71 36 18 38.');});

// The floating navigation becomes opaque as content passes beneath it.
const premiumHeader=document.querySelector('header');
const updateHeader=()=>premiumHeader?.classList.toggle('scrolled',window.scrollY>40);
window.addEventListener('scroll',updateHeader,{passive:true});updateHeader();
// Each service has its own description, photograph and destination link.
const expertiseButtons=[...document.querySelectorAll('[data-service-index]')];
expertiseButtons.forEach(button=>button.addEventListener('click',()=>{
  const selected=button.dataset.serviceIndex;
  expertiseButtons.forEach(item=>{
    const active=item.dataset.serviceIndex===selected;
    item.setAttribute('aria-expanded',String(active));
    document.getElementById(item.getAttribute('aria-controls')).hidden=!active;
  });
  document.querySelectorAll('[data-service-visual]').forEach(visual=>visual.hidden=visual.dataset.serviceVisual!==selected);
}));
